from solution import count_Odd_Squares


def test_issue_example_5_100():
    """Check example: count_Odd_Squares(5,100) == 8."""
    assert count_Odd_Squares(5, 100) == 8  # floor(sqrt(100))=10, ceil(sqrt(5))=3, 10-3+1=8


def test_issue_single_square():
    """Find number of elements with odd factors in single-element square range [9,9]."""
    assert count_Odd_Squares(9, 9) == 1  # floor(sqrt(9))=3, ceil(sqrt(9))=3, 3-3+1=1


def test_issue_single_nonsquare_below():
    """Find number of elements with odd factors in single-element range [8,8] just below a square."""
    assert count_Odd_Squares(8, 8) == 0  # 2*2=4 < 8 < 9=3*3, so 0


def test_issue_single_nonsquare_above():
    """Find number of elements with odd factors in single-element range [10,10] just above a square."""
    assert count_Odd_Squares(10, 10) == 0  # 9=3*3 < 10 < 16=4*4, so 0


def test_issue_both_bounds_squares():
    """Find number of elements with odd factors when both bounds are squares [9,16]."""
    assert count_Odd_Squares(9, 16) == 2  # floor(sqrt(16))=4, ceil(sqrt(9))=3, 4-3+1=2


def test_issue_gap_between_squares():
    """Find number of elements with odd factors in gap between squares [10,15]."""
    assert count_Odd_Squares(10, 15) == 0  # 9=3*3 < 10 and 15 < 16=4*4, so 0


def test_issue_range_one_to_one():
    """Find number of elements with odd factors in range [1,1]."""
    assert count_Odd_Squares(1, 1) == 1  # 1=1*1, so 1


def test_issue_range_one_to_four():
    """Find number of elements with odd factors in range [1,4]."""
    assert count_Odd_Squares(1, 4) == 2  # floor(sqrt(4))=2, ceil(sqrt(1))=1, 2-1+1=2


def test_issue_range_one_to_hundred():
    """Find number of elements with odd factors in range [1,100]."""
    assert count_Odd_Squares(1, 100) == 10  # floor(sqrt(100))=10, ceil(sqrt(1))=1, 10-1+1=10


def test_issue_no_square_small_range():
    """Find number of elements with odd factors in small range with no squares [5,8]."""
    assert count_Odd_Squares(5, 8) == 0  # 4=2*2 < 5 and 8 < 9=3*3, so 0


def test_contract_count_within_range_size():
    """Number of elements in a given range cannot exceed the range size."""
    assert count_Odd_Squares(5, 100) <= 96  # range size 100-5+1=96, so count <= 96


def test_contract_count_nonnegative():
    """Number of elements with odd factors in a given range cannot be negative."""
    assert count_Odd_Squares(10, 15) >= 0  # range size 15-10+1=6, expected 0, 0>=0
